import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787052896000}`),a={name:`reference/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-1-3-2026-08-18" tabindex="-1">[0.1.3] - 2026-08-18 <a class="header-anchor" href="#_0-1-3-2026-08-18" aria-label="Permalink to “[0.1.3] - 2026-08-18”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>http://[::1]:…</code> no longer produces the &quot;plain http to a non-local host, the API password will be sent unencrypted&quot; warning. <code>URL.hostname</code> keeps the brackets around an IPv6 literal, so the loopback check never matched that notation.</li></ul><h2 id="_0-1-2-2026-08-18" tabindex="-1">[0.1.2] - 2026-08-18 <a class="header-anchor" href="#_0-1-2-2026-08-18" aria-label="Permalink to “[0.1.2] - 2026-08-18”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The architecture diagram and the demo recording were not displayed at all — on GitHub or on npm. GitHub Pages had never issued the TLS certificate for freshrss-mcp.ni-c.de (<code>https_enforced</code> was <code>false</code>, the only repository where it was), so every image embedded from that domain was proxied by camo and answered with 502. The certificate has been reissued and HTTPS is enforced.</li><li>The architecture diagram no longer depends on the reader&#39;s operating system. It carried a <code>prefers-color-scheme</code> block, which resolves against the OS rather than the theme toggle of GitHub or npm — so dark-mode readers on a light OS got the light artwork on a dark page, and this diagram painted an opaque white rectangle over the full canvas, which is the worst case there. The README now uses <code>&lt;picture&gt;</code>, which is resolved against the page, and the <code>&lt;img&gt;</code> that npm falls back to brings its own card instead of a media query.</li><li>The documentation site declared no <code>og:image</code> at all, so links to it had no preview card anywhere.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The diagram is generated from a single source, <code>docs/assets/architecture.source.svg</code>, by <code>npm run assets</code>. The rendered copies had already drifted apart; CI now fails if one of them is edited by hand.</li><li><code>docs/public/og.png</code> is generated at exactly 1280x640, GitHub&#39;s recommended size for a social preview.</li><li>The demo recording is shown on the documentation home page as well, not only in the README, and is pinned to the content column so its width no longer depends on what the vhs tape happened to record.</li><li>The TypeScript major is now parked in <code>.github/dependabot.yml</code> with its reason, instead of living only as an <code>@dependabot ignore</code> on the closed PR #1.</li></ul><h2 id="_0-1-1-2026-08-17" tabindex="-1">[0.1.1] - 2026-08-17 <a class="header-anchor" href="#_0-1-1-2026-08-17" aria-label="Permalink to “[0.1.1] - 2026-08-17”">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>First release published by CI, so this is the first version carrying npm provenance attestations, a GitHub release generated from this file, and an entry in the MCP Registry. 0.1.0 was published by hand to claim the package name and is functionally identical; prefer this version if you verify provenance.</li></ul><h2 id="_0-1-0-2026-08-17" tabindex="-1">[0.1.0] - 2026-08-17 <a class="header-anchor" href="#_0-1-0-2026-08-17" aria-label="Permalink to “[0.1.0] - 2026-08-17”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial release: MCP server for FreshRSS, speaking the Google Reader compatible API at <code>/api/greader.php</code>.</li><li>Read tools: <code>get_user_info</code>, <code>list_feeds</code>, <code>list_categories</code>, <code>get_unread_counts</code>, <code>list_articles</code>, <code>get_articles</code>, <code>list_article_ids</code>, <code>export_opml</code>.</li><li>Write tools: <code>mark_articles</code>, <code>mark_all_as_read</code>, <code>subscribe_feed</code>, <code>update_feed</code>, <code>unsubscribe_feed</code>, <code>rename_category_or_label</code>, <code>delete_category_or_label</code>, <code>import_opml</code>. Not registered when <code>FRESHRSS_READ_ONLY=true</code>.</li><li>Confirmation tokens for <code>mark_all_as_read</code>, <code>unsubscribe_feed</code>, <code>delete_category_or_label</code> and <code>import_opml</code>.</li><li>Plain-text conversion of article HTML with per-article and per-response size budgets.</li><li>Credentials embedded in feed URLs (<code>https://user:password@host/feed</code>, how FreshRSS stores HTTP-auth feeds) are redacted in <code>list_feeds</code> and <code>export_opml</code>.</li><li><code>subscribe_feed</code> refuses loopback and link-local targets: FreshRSS fetches the URL server-side, so the tool would otherwise be an SSRF primitive reachable from text inside an article. Private LAN addresses stay allowed.</li><li><code>import_opml</code> refuses documents with a <code>&lt;!DOCTYPE&gt;</code> or <code>&lt;!ENTITY&gt;</code> declaration, which is what carries entity-expansion and external-entity attacks into the FreshRSS server&#39;s XML parser.</li><li>Multi-architecture container image on <code>ghcr.io/ni-c/freshrss-mcp</code> with an SBOM and build provenance. npm is removed from the runtime image — it is unused there, and its vendored dependencies were the image&#39;s only HIGH/CRITICAL CVEs.</li><li>CI: lint, build and tests on Node 22 and 24, <code>npm audit</code>, CodeQL, and a Trivy scan of the image on amd64 and arm64. Releases publish to npm via Trusted Publishing with provenance and register with the MCP Registry.</li></ul>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};